\begin{thm}
\label{fil}
For every cusp metric $d$ on $S_{g, n}$, $g>1, n>0$, there exists a Fuchsian manifold $F$ and an ideal Fuchsian polyhedron $P\subset F$ such that $(S_{g,n}, d)$ is isometric to the upper boundary of $P$. Moreover, $F$ and $P$ are unique up to isometry.
\end{thm}

