In this subsection, let us collect all the properties of the weights that will be considered in the paper. See \cite[Chapter 9]{grafakos2004classical} for the details concerning this subsection.
\begin{definition}[Strong Muckenhoupt Weight]
\label{muck_weight}
A non negative, locally integrable function $\omega$ is a \emph{strong weight} in $A_q(\RR^{n+1})$ for some $1 < q < \infty$ if 
\begin{equation*}
\label{m_wght}
\sup_{\mathfrak{z} \in \RR^{n+1}}\sup_{\substack{0<\rho<\infty,\\0<s<\infty}} \lbr \Yint\tiltlongdash_{Q_{\rho,s}(\mathfrak{z})} \omega(z) \ dz \rbr \lbr \Yint\tiltlongdash_{Q_{\rho,s}(\mathfrak{z})}\omega^{\frac{-1}{q-1}}(z) \ dz \rbr^{q-1} =: [\omega]_{q} < \infty.
\end{equation*}


In the case $q =1$, we define the \emph{strong $A_1(\RR^{n+1})$ weight} to be the class of non negative, locally integrable function $\omega \in A_1(\RR^{n+1})$ satisfying
\begin{equation*}
\label{m_wght_1}
\sup_{z \in \RR^{n+1}}\sup_{\substack{0<\rho<\infty,\\0<s<\infty}} \lbr \Yint\tiltlongdash_{Q_{\rho,s}(\mathfrak{z})} \omega(z) \ dz \rbr \norm{\omega^{-1}}_{L^{\infty}(Q_{\rho,s}(\mathfrak{z}))} =: [\omega]_{1} < \infty.
\end{equation*}


The quantity $[w]_q$ for $1\leq q < \infty$ will be called as the $A_q$ constant of the weight $\omega$. 
\end{definition}

