\begin{equation}\label{splitting}
\mbox{\boldmath$g$}=\mbox{\boldmath$g$}_+\oplus \mbox{\boldmath$g$}_-, \quad [\mbox{\boldmath$g$}_+,\mbox{\boldmath$g$}_+]\subset \mbox{\boldmath$g$}_+, \quad [\mbox{\boldmath$g$}_-,\mbox{\boldmath$g$}_-]\subset \mbox{\boldmath$g$}_-.
