\subsection{Over the simplex category}

In what follows, we will identify partially ordered sets, henceforth referred as posets, with small categories having at most one morphism between each two objects.

\begin{opr}
Denote by $[n]$ the category
$$
[n ] = 0 \to 1 \to 2 \to ... \to n
$$
with exactly one morphism from $i \to j$ when $i \leq j$, and no other morphisms.
Denote by $\Delta$ the full subcategory of ${\rm \bf Cat }$ consisting of categories $[n]$ for $n \geq 0$.
\end{opr}

\begin{lemma} Each morphism in $\Delta$ can be factored as a surjection (in the poset sense) followed by an injection (in the poset sense). Surjections and injections form a factorisation system $(\Delta_s,\Delta_i)$ on $\Delta$ which, together with the natural choice of a degree, $deg [n] = n$, makes it into a Reedy category.
\end{lemma}
\proof Clear. \hfill\ensuremath{\square}\par\medskip
\begin{corr}
 The category $\Delta^{\sf op}$ is a Reedy category for the factorisation system $(\Delta^{\sf op}_-,\Delta^{\sf op}_+)$ consisting of (the opposites of) injections and surjections.
\end{corr}

\begin{opr}
 A map $\rho:[m] \to [n]$ of $\Delta$ is \emph{a Segal inclusion}, or simply \emph{Segal} iff it is an interval inclusion of $[m]$ as first $m+1$ elements of $[n]$, i.e. $\rho(i) = i$ for $0 \leq i \leq m$. In particular, $m$ should be less or equal than $n$.

 A map $\zeta: [n] \to [m]$ of $\Delta$ is \emph{anchor} iff it preserves the endpoints: $\zeta(n) = m$.
\end{opr}

We denote by $\mathrm{A}$, $\Sigma$ the subcategories of anchor and Segal maps in $\Delta$. It is easy to see that $(\mathrm{A},\Sigma)$ is a factorisation system on $\Delta$.

\begin{opr}
 A \emph{Segal factorisation system} on $\Delta^{\sf op}$ consists of the pair $(\mathscr{S},\mathscr{A})$ where $\mathscr{S}$ is the subcategory of Segal maps induced from $\Sigma^{\sf op}$, and $\mathscr{A}$ is the subcategory of anchor maps induced from $\mathrm{A}^{\sf op}$.
\end{opr}

\begin{lemma}
 The identity functor sends $\Delta^{\sf op}_+$  to $\mathscr{A}$. \hfill\ensuremath{\square}\par\medskip
\end{lemma}


\begin{opr}
 A $\Delta$-indexed category is a discrete Grothendieck opfibration $\pi: {\mathcal X} \to \Delta^{\sf op}$ (that is, every map of ${\mathcal X}$ is $\pi$-opcartesian). In particular, there exist a unique, up to isomorphism, simplicial set representing $\pi$ through the Grothendieck construction.
\end{opr}
We shall often write ${\mathcal X}$ instead of $\pi$, when this abuse of notation leads to no confusion.


