\begin{opr}
 An object $x \in {\mathcal X}$ is \emph{degenerate} if there exists a non-identity degree-raising map $y \to x$ of ${\mathcal X}_+$. An object $x$ is thus non-degenerate iff ${\mathcal X}_+ \/ x = \{ id: x \to x\}$, or, equivalently, $Lat(x) = \emptyset$.
\end{opr}

