The main result of this section is the following Riesz representation theorem for subharmonic functions. The essential feature here are the explicitly computable constants.  Recall that a subharmonic function in some domain $\Omega\subset\set{C}$ is an upper semicontinuous function $u:\Omega\to\set{R}\cup\{-\infty\}$ which satisfies the sub-mean value property in $\Omega$. 

\begin{thm}\label{Riesz}
Let $1<R_2<R_1<R$ and let $v:\overline{D_R}\to \set{R}\cup\{-\infty\}$ be a subharmonic function satisfying 
\begin{equation}
v(z)\leq B,\qquad v(0)=m.
\end{equation}
Then, for all $w\in D_{R_1}$, we have the Riesz representation
\begin{equation}
\label{}
\begin{aligned}
v(w)=&\int_{D_{R_1}} \log\l|z-w\r|\mu(\d z)+h(w),
\end{aligned}
\end{equation}
where
\begin{enumerate}[label=(\roman*)]
\item $\mu$ is a positive measure satisfying the bound
\begin{equation}\label{}
\mu(D_{R_1})\leq \frac{B-m}{\log(R\/R_1)},
\end{equation}
\item $h$ is harmonic on $D_{R_1}$ and satisfies the following bounds
\begin{equation}\label{}
\begin{aligned}
\min_{c\in \set{R}}\max_{|w|\leq R_2}\ |h(w)-c|&\leq B_0(R,R_1,R_2)(B-m),\\
\l|\frac{d^k}{d\varphi^k}h(e(\varphi))\r| &\leq B_k(R,R_1,R_2)(B-m), \qquad (k=1,2),
\end{aligned}
\end{equation}
\end{enumerate}
\end{thm}



