    \implies \log p_{\theta}(\x^{(i)}) &\geq \mathcal{L}(\theta,\phi;\x^{(i)}) \quad \text{since } D_{\text{KL}}(\cdot||\cdot)\geq0
\end{align*}
which can be re-written as:
\begin{align}
    \mathcal{L}(\theta,\phi;\x^{(i)}) &= \mathbb{E}_{\z \sim q_{\phi}(\cdot|\x^{(i)})}[\log p_{\theta}(\x^{(i)}|\z)] - D_{\text{KL}}(q_{\phi}(\z|\x^{(i)})\,\|\,p_{\theta}(\z)).
\end{align}

\begin{proof}
    \begin{align*}
